import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { User, Edit, LogOut, Trophy, Zap, Flame, BookOpen, Award, X, Mail } from "lucide-react";
import "../App.css";

const Profile = () => {
  const navigate = useNavigate();
  const [isEditing, setIsEditing] = useState(false);

  // 1. INITIAL STATE (The "Stock Photo")
  // We use "Student" as a generic placeholder now instead of Srija
  const [userData, setUserData] = useState({
    name: "Student",
    email: "loading...",
    grade: "Grade 10",
    school: "Govt High School",
    xp: 402, streak: 3, quizzes: 9, avgScore: "76%"
  });

  // 2. THE FIX: Load Real Data (Putting your photo in the frame)
  useEffect(() => {
    // Read the real name saved during Login
    const realName = localStorage.getItem("userName");
    const realEmail = localStorage.getItem("userEmail");

    // If we find a real name, UPDATE the state immediately
    if (realName) {
      setUserData(prevData => ({
        ...prevData,
        name: realName,
        email: realEmail || "No Email Found"
      }));
    }
  }, []); // <--- This runs once when the page loads

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  return (
    <div className="page-wrapper">

       {/* --- Main Profile Content --- */}
       <div className="dashboard-container">

         {/* Header Card */}
         <div className="profile-header-card">
           <div className="profile-banner"></div>
           <div className="profile-info-row">
             <div className="profile-avatar-box">
               <User size={64} color="#10b981" />
             </div>

             <div className="profile-text">
               {/* 3. DISPLAY THE REAL NAME */}
               <h1 className="profile-name">{userData.name}</h1>
               <p className="profile-subtext">{userData.grade} • {userData.email}</p>
             </div>

             <div className="profile-buttons">
               <button className="btn-edit" onClick={() => setIsEditing(true)}>
                 <Edit size={16} /> Edit Profile
               </button>
               <button className="btn-signout" onClick={handleLogout}>
                 <LogOut size={16} /> Sign Out
               </button>
             </div>
           </div>
         </div>

         {/* Stats Row (Keeping your existing UI) */}
         <div className="stats-grid-row">
            <div className="stat-card">
               <Zap size={24} color="#f59e0b" />
               <h3>{userData.xp}</h3>
               <p>Total XP</p>
            </div>
            <div className="stat-card">
               <Flame size={24} color="#ef4444" />
               <h3>{userData.streak} Day</h3>
               <p>Streak</p>
            </div>
            <div className="stat-card">
               <Trophy size={24} color="#eab308" />
               <h3>{userData.avgScore}</h3>
               <p>Avg Score</p>
            </div>
         </div>

       </div>

       {/* --- Edit Profile Modal (Popup) --- */}
       {isEditing && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3>Edit Profile</h3>
              <X className="close-icon" onClick={() => setIsEditing(false)} />
            </div>
            <div className="modal-body">
              <label>Full Name</label>
              <input 
                type="text" 
                value={userData.name} 
                onChange={(e) => setUserData({...userData, name: e.target.value})}
              />

              <label>Grade</label>
              <select 
                value={userData.grade} 
                onChange={(e) => setUserData({...userData, grade: e.target.value})}
              >
                <option>Grade 9</option>
                <option>Grade 10</option>
                <option>Grade 11</option>
              </select>

              <div className="modal-footer">
                <button className="btn-cancel" onClick={() => setIsEditing(false)}>Cancel</button>
                <button className="btn-save" onClick={() => {
                    // Save the new name to memory permanently
                    localStorage.setItem("userName", userData.name);
                    setIsEditing(false);
                }}>Save Changes</button>
              </div>
            </div>
          </div>
        </div>
       )}

    </div>
  );
};

export default Profile;
